import {ToolRegistry} from './registry.js';
import {jest} from '@jest/globals';
import type {ToolDefinition} from '../../types/ai.js';
import type {ToolExecutor} from './registry.js';

describe('ToolRegistry', () => {
  describe('rejects input missing a required property and never calls the executor ([validated by specs/hal-engine-tool-input-validation/spec.md#1])', () => {
    it('does not invoke the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalled = false;
      registry.register(
        {
          name: 'test-tool',
          description: 'Test tool',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
        },
        async () => {
          executorCalled = true;
          return 'success';
        }
      );
      await registry.execute('test-tool', {});
      expect(executorCalled).toBe(false);
    });

    it('returns a result containing the missing property', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test-tool',
          description: 'Test tool',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
        },
        async () => 'success'
      );
      const result = await registry.execute('test-tool', {});
      expect(result).toEqual({result: expect.stringContaining('location')});
    });
  });

  describe('valid input with an unlisted extra property is passed through to the executor unchanged exactly once ([validated by specs/hal-engine-tool-input-validation/spec.md#3])', () => {
    it('passes input unchanged', async () => {
      const registry = new ToolRegistry();
      const executor = jest.fn<ToolExecutor>(async () => 'success');
      registry.register(
        {
          name: 'test-tool',
          description: 'Test tool',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
        },
        executor
      );
      const input = {location: 'paris', extra: 123};
      await registry.execute('test-tool', input);
      expect(executor).toHaveBeenCalledWith(input, undefined);
    });
  });

  describe('rejects a wrong-typed field with a message naming the field path and expected type without offending value ([validated by specs/hal-engine-tool-input-validation/spec.md#2])', () => {
    it('rejects without offending value', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test-tool',
          description: 'Test tool',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
        },
        async () => 'success'
      );
      const result = (await registry.execute('test-tool', {location: 123})) as {result: string};
      expect(result.result).not.toContain('123');
    });
  });

  it('throws at register time for an uncompilable schema naming the tool ([validated by specs/hal-engine-tool-input-validation/spec.md#5])', () => {
    const registry = new ToolRegistry();
    expect(() => {
      registry.register(
        {
          name: 'bad-tool',
          description: 'Bad tool',
          inputSchema: {type: 'invalid-type'},
        } as unknown as ToolDefinition,
        async () => 'success'
      );
    }).toThrow(/bad-tool/);
  });

  describe('validates a function-valued tool definition against the schema current at that call ([validated by specs/hal-engine-tool-input-validation/spec.md#7])', () => {
    it('validates against new schema', async () => {
      const registry = new ToolRegistry();
      let schemaType = 'string';
      const source = () =>
        ({
          name: 'dynamic-tool',
          description: 'Dynamic tool',
          inputSchema: {type: 'object', properties: {value: {type: schemaType}}},
        }) as ToolDefinition;
      registry.register(source, async () => 'success');

      await registry.execute('dynamic-tool', {value: 'test'});
      schemaType = 'number';
      const result2 = (await registry.execute('dynamic-tool', {value: 'test'})) as {result?: string};
      expect(result2.result).toBeDefined();
    });
  });

  it('compiles a static tool schema once across multiple execute calls ([validated by specs/hal-engine-tool-input-validation/spec.md#6])', async () => {
    const registry = new ToolRegistry();
    let getterCalled = 0;
    const def = {name: 'static-tool', description: 'Static tool'} as ToolDefinition;
    Object.defineProperty(def, 'inputSchema', {
      get: () => {
        getterCalled++;
        return {type: 'object', properties: {val: {type: 'string'}}};
      },
    });
    registry.register(def, async () => 'success');
    for (let i = 0; i < 10; i++) {
      await registry.execute('static-tool', {val: 'test'});
    }
    expect(getterCalled).toBe(1);
  });

  it('throws Unknown tool for an unregistered name ([validated by specs/hal-engine-tool-input-validation/spec.md#4])', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unknown-tool', {})).rejects.toThrow('Unknown tool: unknown-tool');
  });
});

